var a=[{title:`Ce descriu tiparele`,text:`O genuflexiune îndoaie și îndreaptă în principal șoldurile, genunchii și gleznele împreună. O balansare din șold se mișcă mai ales din șolduri, iar fandările și urcările pe treaptă încarcă un picior pe rând. Împingerea mută rezistența departe de corp, iar tragerea o aduce spre corp. La o plimbare cu greutate ții o sarcină stabilă în timp ce mergi, exercițiile pentru trunchi se opun mișcării trunchiului sau o produc, iar locomoția cuprinde mersul, alergarea și mișcările asemănătoare.`},{title:`De ce contează tiparele`,text:`Un singur exercițiu poate antrena mai mulți mușchi și mai multe tipare deodată. O genuflexiune goblet antrenează picioarele și trunchiul, iar o plimbare cu greutate antrenează priza, postura și mecanica mersului. Sortarea exercițiilor pe tipare arată lacune pe care o listă sortată doar pe piept, brațe și picioare le poate rata. Nu ai nevoie de toate tiparele în fiecare antrenament.`},{title:`Un echilibru pe parcursul săptămânii`,text:`În două sau trei sesiuni pentru tot corpul, un începător poate include o genuflexiune, o balansare din șold, o împingere orizontală, o tragere orizontală, o fandare și un exercițiu simplu împotriva rotației sau a extensiei. Împingerile verticale, tragerile verticale și plimbările cu greutate pot intra în program când echipamentul, mobilitatea și obiectivele ți-o permit. Păstrează doza pentru fiecare tipar suficient de mică încât să te poți reface și sari peste exercițiile de care nu ai nevoie.`},{title:`Potrivește tiparele cu abilitățile`,text:`Fiecare tipar are variante mai ușoare și mai grele. O genuflexiune la scaun poate veni înaintea unei genuflexiuni goblet, iar o flotare la perete înaintea uneia pe podea. Un ramat la cablu și unul cu gantera sunt ambele trageri orizontale, dar cer echilibru și echipament diferite. Dacă o mișcare provoacă disconfort sau pare instabilă, schimbă varianta și păstrează tiparul.`},{title:`Folosirea TrainUp`,text:`Fiecare pagină de exercițiu din Explorează arată tiparul de mișcare, așa că poți verifica în ce măsură săptămâna planificată le acoperă. Dacă majoritatea sesiunilor conțin împingeri și aproape deloc trageri, un ramat sau o tragere la piept potrivite cu echipamentul și limitările tale ar umple golul. Urmărește o acoperire bună pe parcursul săptămânilor, nu un raport perfect în fiecare sesiune.`}];var r=[{label:`NSCA: bazele siguranței și ale antrenamentului de forță`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};